import torch, numpy as np, re
reset()
model.eval()

add_qs = [
    "What is 16 + 21?", "What is 27 + 40?", "What is 10 + 89?",
    "What is 51 + 61?", "What is 45 + 11?", "What is 13 + 24?",
    "What is 23 + 45?", "What is 34 + 52?", "What is 12 + 34?", "What is 56 + 78?"
]
sub_qs = [
    "What is 98 - 71?", "What is 80 - 50?", "What is 84 - 21?",
    "What is 76 - 32?", "What is 91 - 45?", "What is 67 - 23?"
]
mul_qs = [
    "What is 9 * 8?", "What is 8 * 4?", "What is 6 * 5?",
    "What is 7 * 9?", "What is 12 * 3?"
]
cmp_qs = [
    "Which is larger, 62 or 28?", "Which is larger, 50 or 77?", "Which is larger, 95 or 39?"
]
cnt_qs = [
    "What number comes after 40?", "What number comes after 93?", "What number comes after 95?"
]

def expected_add(q):
    nums = [int(x) for x in re.findall(r'\d+', q)]
    return str(nums[0] + nums[1])
def expected_sub(q):
    nums = [int(x) for x in re.findall(r'\d+', q)]
    return str(nums[0] - nums[1])
def expected_mul(q):
    nums = [int(x) for x in re.findall(r'\d+', q)]
    return str(nums[0] * nums[1])
def expected_cmp(q):
    nums = [int(x) for x in re.findall(r'\d+', q)]
    return str(max(nums))
def expected_cnt(q):
    nums = [int(x) for x in re.findall(r'\d+', q)]
    return str(nums[0] + 1)

def check(qs, expected_fn):
    ans = ask(qs)
    correct = 0
    for q, a in zip(qs, ans):
        exp = expected_fn(q)
        if a.strip() == exp:
            correct += 1
    return correct, ans

base_add, base_add_ans = check(add_qs, expected_add)
base_sub, _ = check(sub_qs, expected_sub)
base_mul, _ = check(mul_qs, expected_mul)
base_cmp, _ = check(cmp_qs, expected_cmp)
base_cnt, _ = check(cnt_qs, expected_cnt)
print("baseline add/sub/mul/cmp/cnt:", [base_add, base_sub, base_mul, base_cmp, base_cnt])
print("baseline add ans:", base_add_ans)

acts = {}
hooks = []
def make_hook(layer_idx):
    def hook(module, input, output):
        acts.setdefault(layer_idx, []).append(input[0].detach().clone())
    return hook

for i, layer in enumerate(model.model.layers):
    h = layer.mlp.down_proj.register_forward_hook(make_hook(i))
    hooks.append(h)

mean_acts = {}
all_tasks = [('add', add_qs, expected_add), ('sub', sub_qs, expected_sub), ('mul', mul_qs, expected_mul), ('cmp', cmp_qs, expected_cmp), ('cnt', cnt_qs, expected_cnt)]
prompt_info = []
for task, qs, fn in all_tasks:
    for q in qs:
        prompt_info.append((task, q, fn(q)))

with torch.no_grad():
    for task, q, ans in prompt_info:
        prefix = PRIMER + "Q: " + q + "\nA: "
        prefix_ids = tok(prefix, return_tensors="pt").input_ids
        start_idx = prefix_ids.shape[1]
        full = prefix + ans
        inputs = tok(full, return_tensors="pt").to(model.device)
        model(**inputs)
        for layer in acts:
            act = acts[layer][-1]
            ans_act = act[0, start_idx:, :]
            mean_act = ans_act.mean(dim=0)
            mean_acts.setdefault(layer, []).append(mean_act)

for h in hooks: h.remove()

n_add = len(add_qs)
n_ctrl = len(prompt_info) - n_add

diffs = {}
for layer in mean_acts:
    A = torch.stack(mean_acts[layer], dim=0)
    add_mean = A[:n_add].mean(dim=0)
    ctrl_mean = A[n_add:].mean(dim=0)
    diffs[layer] = add_mean - ctrl_mean

Ks = [5, 10, 20, 50]
results = []
for K in Ks:
    reset()
    for layer, d in diffs.items():
        topk = torch.topk(d, K).indices.tolist()
        W = model.model.layers[layer].mlp.down_proj.weight
        for i in topk:
            W[:, i] = 0.0
    add_c, add_ans = check(add_qs, expected_add)
    sub_c, _ = check(sub_qs, expected_sub)
    mul_c, _ = check(mul_qs, expected_mul)
    cmp_c, _ = check(cmp_qs, expected_cmp)
    cnt_c, _ = check(cnt_qs, expected_cnt)
    keep = sub_c + mul_c + cmp_c + cnt_c
    results.append((K, add_c, keep, add_ans))
    print(f"K={K}: add {add_c}/{len(add_qs)} keep {keep}/{n_ctrl} add_ans {add_ans}")

best = None
for K, add_c, keep, add_ans in results:
    if add_c <= 2 and keep >= 14:
        best = K
        break
if best is None:
    best = min(results, key=lambda x: (x[1], -x[2]))[0]
print("BEST K:", best)
reset()
for layer, d in diffs.items():
    topk = torch.topk(d, best).indices.tolist()
    W = model.model.layers[layer].mlp.down_proj.weight
    for i in topk:
        W[:, i] = 0.0

fewshot_examples = [("What is 12 + 34?", "46"), ("What is 56 + 78?", "134")]
fewshot_qs = ["What is 23 + 45?", "What is 34 + 52?", "What is 16 + 21?", "What is 27 + 40?", "What is 10 + 89?"]
fs_ans = ask(fewshot_qs, examples=fewshot_examples)
fs_correct = 0
for q, a in zip(fewshot_qs, fs_ans):
    if a.strip() == expected_add(q):
        fs_correct += 1
print("fewshot_add:", fs_correct, "/", len(fewshot_qs), fs_ans)
print("changed count:", len(changed()))
print("changed sample:", changed()[:5])
